using System.Text.Json;
namespace Studio;
public static class CreativeContract
{
 private static readonly Dictionary<string,Action<JsonElement,Dictionary<string,JsonElement>,List<string>,bool>> Validators=new(){["studio.storyboard.Sequence"]=Story,["studio.configurator.Catalog"]=Catalog,["studio.industrial.Review"]=Review};
 private static string T(JsonElement e,string key)=>DocumentContract.Text(e,key);
 public static void Validate(JsonElement document,List<string> errors,bool publish){var entities=document.GetProperty("entities").EnumerateArray().ToDictionary(e=>T(e,"id"));foreach(var entity in entities.Values)foreach(var component in entity.GetProperty("components").EnumerateArray())if(component.GetProperty("enabled").GetBoolean()&&Validators.TryGetValue(T(component,"type"),out var validate))validate(component.GetProperty("data"),entities,errors,publish);}
 private static void Story(JsonElement data,Dictionary<string,JsonElement> entities,List<string> errors,bool publish){
  var duration=data.GetProperty("duration").GetDouble();var tracks=data.GetProperty("tracks").EnumerateArray().ToArray();var ids=new HashSet<string>();
  foreach(var track in tracks){if(!ids.Add(T(track,"id")))errors.Add("轨道 ID 重复");var clips=track.GetProperty("clips").EnumerateArray().ToArray();foreach(var clip in clips){if(!ids.Add(T(clip,"id")))errors.Add("片段 ID 重复");if(clip.GetProperty("curveStart").GetDouble()>clip.GetProperty("curveEnd").GetDouble())errors.Add("片段求值窗口无效");if(clip.GetProperty("start").GetDouble()+clip.GetProperty("duration").GetDouble()>duration+.000001)errors.Add("片段超出故事板时长");}
   for(var i=0;i<clips.Length;i++)for(var j=i+1;j<clips.Length;j++)if(Overlap(clips[i],clips[j]))errors.Add("同轨片段重叠");
   var channel=T(track,"channel");if(track.GetProperty("muted").GetBoolean()||clips.Length==0)continue;if(publish&&channel=="audio"&&(!entities.TryGetValue(T(track,"targetId"),out var audioTarget)||!audioTarget.GetProperty("components").EnumerateArray().Any(c=>T(c,"type")=="Audio"&&c.GetProperty("enabled").GetBoolean())))errors.Add("音频轨道目标能力不匹配");if(publish&&new[]{"transform","opacity","visibility","annotation","assembly","audio"}.Contains(channel)&&T(track,"targetId")=="")errors.Add("故事板轨道缺少目标");
   if(publish&&channel=="assembly"&&(!entities.TryGetValue(T(track,"targetId"),out var target)||!target.GetProperty("components").EnumerateArray().Any(c=>T(c,"type")=="studio.assembly.Root"&&c.GetProperty("enabled").GetBoolean())))errors.Add("装配轨道目标能力不匹配");
  }
  for(var i=0;i<tracks.Length;i++)for(var j=i+1;j<tracks.Length;j++){var a=tracks[i];var b=tracks[j];if(T(a,"targetId")==T(b,"targetId")&&T(a,"channel")==T(b,"channel")&&a.GetProperty("priority").GetDouble()==b.GetProperty("priority").GetDouble()&&!a.GetProperty("muted").GetBoolean()&&!b.GetProperty("muted").GetBoolean())foreach(var x in a.GetProperty("clips").EnumerateArray())foreach(var y in b.GetProperty("clips").EnumerateArray())if(Overlap(x,y))errors.Add("相同目标通道重叠，需要不同合成优先级");}
 }
 private static bool Overlap(JsonElement a,JsonElement b)=>a.GetProperty("start").GetDouble()<b.GetProperty("start").GetDouble()+b.GetProperty("duration").GetDouble()&&b.GetProperty("start").GetDouble()<a.GetProperty("start").GetDouble()+a.GetProperty("duration").GetDouble();
 private static void Catalog(JsonElement data,Dictionary<string,JsonElement> entities,List<string> errors,bool publish){
  if(!publish)return;var groups=data.GetProperty("groups").EnumerateArray().ToArray();var selections=new Dictionary<string,List<string>>();var numeric=new Dictionary<string,double>();var byId=new Dictionary<string,JsonElement>();
  foreach(var group in groups){var id=T(group,"id");if(!byId.TryAdd(id,group)){errors.Add("属性组 ID 重复");continue;}var options=group.GetProperty("options").EnumerateArray().Select(o=>T(o,"id")).ToHashSet();if(options.Count!=group.GetProperty("options").GetArrayLength())errors.Add("选项 ID 重复");if(group.GetProperty("min").GetDouble()>group.GetProperty("max").GetDouble())errors.Add("选项数量范围无效");var defaults=group.GetProperty("defaultIds").EnumerateArray().Select(i=>i.GetString()!).Distinct().ToList();if(defaults.Any(id=>!options.Contains(id)))errors.Add("默认选项不存在");selections[id]=defaults;if(T(group,"control")=="number")numeric[id]=group.TryGetProperty("numericDefault",out var value)?value.GetDouble():0;}
  var rules=data.GetProperty("rules").EnumerateArray().OrderByDescending(r=>r.GetProperty("priority").GetDouble()).ThenBy(r=>T(r,"id"),StringComparer.Ordinal).ToArray();
  foreach(var rule in rules)foreach(var key in new[]{"when","then"}){var condition=rule.GetProperty(key);if(!byId.TryGetValue(T(condition,"groupId"),out var group)||!(key=="then"&&T(rule,"type") is "range" or "count")&&!group.GetProperty("options").EnumerateArray().Any(o=>T(o,"id")==T(condition,"optionId")))errors.Add("规则引用选项不存在");}
  if(errors.Count>0)return;var visited=new HashSet<string>();for(var pass=0;pass<=Math.Max(16,rules.Length*2);pass++){
   var signature=string.Join('|',selections.Select(p=>p.Key+":"+string.Join(',',p.Value)))+"/"+string.Join('|',numeric.Select(p=>p.Key+":"+p.Value));if(!visited.Add(signature)){errors.Add("规则循环导致配置无法收敛");break;}var changed=false;
   foreach(var rule in rules){var when=rule.GetProperty("when");if(!selections[T(when,"groupId")].Contains(T(when,"optionId")))continue;var then=rule.GetProperty("then");var groupId=T(then,"groupId");var optionId=T(then,"optionId");var list=selections[groupId];var type=T(rule,"type");if(type=="range"&&T(byId[groupId],"control")=="number"){var previous=numeric[groupId];var next=Math.Max(rule.GetProperty("minimum").GetDouble(),Math.Min(rule.GetProperty("maximum").GetDouble(),previous));numeric[groupId]=next;changed=changed||next!=previous;}if(type is "require" or "implies" or "bundle"){if(!list.Contains(optionId)){if(byId[groupId].GetProperty("max").GetDouble()==1)list.Clear();list.Add(optionId);changed=true;}}else if(type=="exclude"){changed=list.Remove(optionId)||changed;}else if(type=="default"&&list.Count==0){list.Add(optionId);changed=true;}}
   if(!changed)break;if(pass==Math.Max(16,rules.Length*2))errors.Add("规则求值超过安全步数");
  }
  foreach(var group in groups){var selected=selections[T(group,"id")];if(T(group,"control")=="number"){var value=numeric[T(group,"id")];var minimum=group.TryGetProperty("numericMinimum",out var lo)?lo.GetDouble():0;var maximum=group.TryGetProperty("numericMaximum",out var hi)?hi.GetDouble():1;if(value<minimum||value>maximum)errors.Add("默认数值超出范围");}if(T(group,"control")!="number"&&(selected.Count<group.GetProperty("min").GetDouble()||selected.Count>group.GetProperty("max").GetDouble()))errors.Add("默认配置选项数量不合法");}
  foreach(var rule in rules){var when=rule.GetProperty("when");if(!selections[T(when,"groupId")].Contains(T(when,"optionId")))continue;var then=rule.GetProperty("then");var selected=selections[T(then,"groupId")];var type=T(rule,"type");if((type is "require" or "implies" or "bundle")&&!selected.Contains(T(then,"optionId")))errors.Add(T(rule,"reason"));if(type=="exclude"&&selected.Contains(T(then,"optionId")))errors.Add(T(rule,"reason"));if(type=="count"&&(selected.Count<rule.GetProperty("minimum").GetDouble()||selected.Count>rule.GetProperty("maximum").GetDouble()))errors.Add(T(rule,"reason"));if(type=="range"&&T(byId[T(then,"groupId")],"control")!="number")foreach(var id in selected){var option=byId[T(then,"groupId")].GetProperty("options").EnumerateArray().First(o=>T(o,"id")==id);if(!double.TryParse(T(option,"name"),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var value)||value<rule.GetProperty("minimum").GetDouble()||value>rule.GetProperty("maximum").GetDouble())errors.Add(T(rule,"reason"));}}
 }
 private static void Review(JsonElement data,Dictionary<string,JsonElement> entities,List<string> errors,bool publish){
  foreach(var color in data.GetProperty("colors").EnumerateArray())if(T(color,"mode")=="range"&&color.GetProperty("min").GetDouble()>=color.GetProperty("max").GetDouble())errors.Add("连续颜色范围需要递增的上下界");
  var classes=data.GetProperty("classes").EnumerateArray().ToArray();var byId=new Dictionary<string,JsonElement>();foreach(var c in classes){if(!byId.TryAdd(T(c,"id"),c))errors.Add("分类 ID 重复");if(c.GetProperty("fields").EnumerateArray().Select(f=>T(f,"id")).Distinct().Count()!=c.GetProperty("fields").GetArrayLength())errors.Add("属性字段 ID 重复");}
  foreach(var c in classes){var seen=new HashSet<string>();var cursor=c;while(true){if(!seen.Add(T(cursor,"id"))){errors.Add("分类层级循环");break;}var parent=T(cursor,"parentId");if(parent=="")break;if(!byId.TryGetValue(parent,out cursor)){errors.Add("分类父项不存在");break;}}}
  if(publish)foreach(var measurement in data.GetProperty("measurements").EnumerateArray())if(measurement.TryGetProperty("anchorRefs",out var anchors))foreach(var anchor in anchors.EnumerateArray()){
   if(!entities.TryGetValue(T(anchor,"entityId"),out var entity)){errors.Add("测量目标丢失");continue;}var binding=entity.GetProperty("components").EnumerateArray().FirstOrDefault(c=>T(c,"type")=="ModelNode"&&c.GetProperty("enabled").GetBoolean());if(T(anchor,"sourceRevision")!=""&&(binding.ValueKind==JsonValueKind.Undefined||T(binding.GetProperty("data"),"meshRevision")!=T(anchor,"sourceRevision"))||T(anchor,"sourceElementId")!=""&&(binding.ValueKind==JsonValueKind.Undefined||T(binding.GetProperty("data"),"sourceElementId")!=T(anchor,"sourceElementId")))errors.Add("测量来源已变化");
  }
 }
}
